const delay = (ms, value) => new Promise(res => setTimeout(() => res(value), ms));

async function pool(tasks, limit) {
  const results = new Array(tasks.length);
  let next = 0, active = 0, peak = 0;
  return new Promise((resolve) => {
    const launch = () => {
      while (active < limit && next < tasks.length) {
        const i = next++;
        active++;
        peak = Math.max(peak, active);
        tasks[i]().then(v => {
          results[i] = v;
          active--;
          if (next === tasks.length && active === 0) resolve({ results, peak });
          else launch();
        });
      }
    };
    launch();
  });
}

async function main() {
  const tasks = [0, 1, 2, 3, 4, 5].map(i => () => delay(30, "task-" + i));
  const { results, peak } = await pool(tasks, 2);
  console.log("results:", results.join(", "));
  console.log("peak in flight:", peak);
}
main();

