import asyncio

counts = {"transient": 0, "final": 0}

class TransientError(Exception): pass
class FinalError(Exception): pass

async def call(kind):
    counts[kind] += 1
    if kind == "transient" and counts[kind] < 3:
        raise TransientError("try again later")
    if kind == "final":
        raise FinalError("no such resource")
    return "ok"

async def with_retry(fn, retry_on, tries=4):
    for attempt in range(1, tries + 1):
        try:
            return await fn()
        except retry_on:
            if attempt == tries:
                raise
            await asyncio.sleep(0.01)

async def main():
    print("transient call:", await with_retry(lambda: call("transient"), TransientError))
    print("transient attempts:", counts["transient"])
    try:
        await with_retry(lambda: call("final"), TransientError)
    except FinalError as e:
        print("final call raised immediately:", e)
    print("final attempts:", counts["final"])

asyncio.run(main())

