import asyncio

async def attempt(n, outcomes):
    try:
        if n == 1:
            await asyncio.wait_for(asyncio.sleep(0.2), timeout=0.05)
        else:
            await asyncio.wait_for(asyncio.sleep(0.01), timeout=0.05)
        outcomes.append(f"attempt {n}: success")
        return "data"
    except TimeoutError:
        outcomes.append(f"attempt {n}: timed out")
        raise

async def main():
    outcomes = []
    for n in (1, 2):
        try:
            result = await attempt(n, outcomes)
            break
        except TimeoutError:
            if n == 2:
                raise
    print("result:", result)
    print("history:", outcomes)

asyncio.run(main())

