import asyncio

async def work(n):
    if n == 3:
        await asyncio.sleep(0.2)      # will blow the 80ms budget
        return "slow data"
    if n == 4:
        await asyncio.sleep(0.01)
        raise ValueError("job 4 is invalid")
    await asyncio.sleep(0.03)
    return f"data-{n}"

async def attempt(n, sem):
    async with sem:
        try:
            return ("ok", await asyncio.wait_for(work(n), timeout=0.08))
        except TimeoutError:
            return ("timeout", None)
        except ValueError:
            return ("error", None)

async def main():
    sem = asyncio.Semaphore(2)
    outcomes = await asyncio.gather(*(attempt(n, sem) for n in range(1, 7)))
    for n, (status, _) in enumerate(outcomes, start=1):
        print(f"job {n}: {status}")
    counts = {}
    for status, _ in outcomes:
        counts[status] = counts.get(status, 0) + 1
    print("summary:", counts)

asyncio.run(main())
